#!/data/data/com.termux/files/usr/bin/bash
set -e

RES="app/src/main/res"
JAVA_FILE="app/src/main/java/com/android/gallery3d/app/GalleryActivity.java"
MAIN_LAYOUT="app/src/main/res/layout/main.xml"
STRINGS="app/src/main/res/values/strings.xml"

echo "== Criando drawables da barra inferior =="
cat > "$RES/drawable/bottom_nav_pill_background.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<shape xmlns:android="http://schemas.android.com/apk/res/android"
        android:shape="rectangle">
    <solid android:color="#2A2A2E" />
    <corners android:radius="32dp" />
</shape>
EOF

cat > "$RES/drawable/bottom_nav_selected_pill.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<shape xmlns:android="http://schemas.android.com/apk/res/android"
        android:shape="rectangle">
    <solid android:color="#4285f4" />
    <corners android:radius="24dp" />
</shape>
EOF

cat > "$RES/drawable/ic_nav_gallery3d.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
        android:width="24dp"
        android:height="24dp"
        android:viewportWidth="24"
        android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFFFF"
        android:pathData="M4,4h10v10H4V4zM6,6v6h6V6H6zM14,4h6v6h-6V4zM16,6v2h2V6h-2zM4,16h6v4H4v-4zM6,18v0h2v0H6zM14,14h6v10h-6V14zM16,16v6h2v-6h-2z"/>
</vector>
EOF

cat > "$RES/drawable/ic_nav_music3d.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
        android:width="24dp"
        android:height="24dp"
        android:viewportWidth="24"
        android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFFFF"
        android:pathData="M12,3v10.55c-0.59,-0.34 -1.27,-0.55 -2,-0.55 -2.21,0 -4,1.79 -4,4s1.79,4 4,4 4,-1.79 4,-4V7h4V3h-6z"/>
</vector>
EOF

echo "== Criando layout da barra inferior =="
cat > "$RES/layout/bottom_nav_bar.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"
        android:id="@+id/bottom_nav_bar"
        android:layout_width="wrap_content"
        android:layout_height="64dp"
        android:layout_alignParentBottom="true"
        android:layout_centerHorizontal="true"
        android:layout_marginBottom="24dp"
        android:orientation="horizontal"
        android:background="@drawable/bottom_nav_pill_background"
        android:elevation="12dp"
        android:paddingLeft="8dp"
        android:paddingRight="8dp"
        android:paddingTop="8dp"
        android:paddingBottom="8dp">

    <LinearLayout
            android:id="@+id/nav_tab_gallery3d"
            android:layout_width="wrap_content"
            android:layout_height="match_parent"
            android:orientation="horizontal"
            android:gravity="center"
            android:clickable="true"
            android:focusable="true"
            android:background="@drawable/bottom_nav_selected_pill"
            android:paddingLeft="20dp"
            android:paddingRight="20dp">

        <ImageView
                android:layout_width="22dp"
                android:layout_height="22dp"
                android:src="@drawable/ic_nav_gallery3d"
                android:contentDescription="@string/nav_tab_gallery3d" />

        <TextView
                android:id="@+id/nav_tab_gallery3d_label"
                android:layout_width="wrap_content"
                android:layout_height="wrap_content"
                android:layout_marginLeft="8dp"
                android:text="@string/nav_tab_gallery3d"
                android:textColor="#FFFFFF"
                android:textSize="14sp"
                android:textStyle="bold" />
    </LinearLayout>

    <View
            android:layout_width="8dp"
            android:layout_height="1dp" />

    <LinearLayout
            android:id="@+id/nav_tab_music3d"
            android:layout_width="wrap_content"
            android:layout_height="match_parent"
            android:orientation="horizontal"
            android:gravity="center"
            android:clickable="true"
            android:focusable="true"
            android:background="@android:color/transparent"
            android:paddingLeft="20dp"
            android:paddingRight="20dp">

        <ImageView
                android:layout_width="22dp"
                android:layout_height="22dp"
                android:src="@drawable/ic_nav_music3d"
                android:contentDescription="@string/nav_tab_music3d" />

        <TextView
                android:id="@+id/nav_tab_music3d_label"
                android:layout_width="wrap_content"
                android:layout_height="wrap_content"
                android:layout_marginLeft="8dp"
                android:text="@string/nav_tab_music3d"
                android:textColor="#A9ABAD"
                android:textSize="14sp"
                android:textStyle="bold" />
    </LinearLayout>

</LinearLayout>
EOF

cat > "$RES/layout/music3d_placeholder.xml" << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<FrameLayout xmlns:android="http://schemas.android.com/apk/res/android"
        android:id="@+id/music3d_placeholder_root"
        android:layout_width="match_parent"
        android:layout_height="match_parent"
        android:background="#1A1A1A"
        android:visibility="gone">

    <LinearLayout
            android:layout_width="wrap_content"
            android:layout_height="wrap_content"
            android:layout_gravity="center"
            android:orientation="vertical"
            android:gravity="center">

        <ImageView
                android:layout_width="64dp"
                android:layout_height="64dp"
                android:src="@drawable/ic_nav_music3d"
                android:alpha="0.6" />

        <TextView
                android:layout_width="wrap_content"
                android:layout_height="wrap_content"
                android:layout_marginTop="16dp"
                android:text="@string/music3d_coming_soon"
                android:textColor="#A9ABAD"
                android:textSize="16sp" />
    </LinearLayout>
</FrameLayout>
EOF

echo "== Adicionando strings novas =="
if ! grep -q "nav_tab_gallery3d" "$STRINGS"; then
  sed -i 's#<string name="no_permission_message">.*</string>#&\n    <string name="nav_tab_gallery3d">Galeria3D</string>\n    <string name="nav_tab_music3d">Music3D</string>\n    <string name="music3d_coming_soon">Em construcao</string>#' "$STRINGS"
fi
grep -n "nav_tab_gallery3d\|nav_tab_music3d\|music3d_coming_soon" "$STRINGS"

echo "== Incluindo barra e placeholder no main.xml =="
python3 - << 'PYEOF'
path = "app/src/main/res/layout/main.xml"
with open(path) as f:
    content = f.read()

old = "</RelativeLayout>"
new = '''    <include layout="@layout/music3d_placeholder"/>
    <include layout="@layout/bottom_nav_bar"/>
</RelativeLayout>'''

if "bottom_nav_bar" not in content:
    assert content.count(old) == 1
    content = content.replace(old, new)
    with open(path, "w") as f:
        f.write(content)
    print("main.xml atualizado.")
else:
    print("main.xml ja tinha a barra, pulando.")
PYEOF

echo "== Restaurando GalleryActivity.java com a barra inferior integrada =="
base64 -d > "$JAVA_FILE" << 'B64_EOF'

B64_EOF

echo "== Fim: bottom nav instalado =="
